text = input().strip()
counts = {vowel: 0 for vowel in 'aeiou'}
covered = left = 0
best = len(text) + 1
for right, char in enumerate(text):
    if char in counts:
        if counts[char] == 0:
            covered += 1
        counts[char] += 1
    while covered == 5:
        best = min(best, right - left + 1)
        outgoing = text[left]
        if outgoing in counts:
            counts[outgoing] -= 1
            if counts[outgoing] == 0:
                covered -= 1
        left += 1
print(best if best <= len(text) else -1)

