#include <algorithm>
#include <array>
#include <iostream>
#include <string>
using namespace std;
int main() { string s; cin >> s; array<int, 26> count{}; auto vowel = [](char c) { return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'; }; int covered = 0, left = 0, best = (int)s.size() + 1; for (int right = 0; right < (int)s.size(); ++right) { char c = s[right]; if (vowel(c)) { if (count[c - 'a']++ == 0) ++covered; } while (covered == 5) { best = min(best, right - left + 1); char out = s[left++]; if (vowel(out) && --count[out - 'a'] == 0) --covered; } } cout << (best <= (int)s.size() ? best : -1) << '\n'; }
